-- Create legislators table
CREATE TABLE legislators (
  id SERIAL PRIMARY KEY,
  chamber TEXT NOT NULL CHECK (chamber IN ('senate', 'assembly')),
  district INTEGER NOT NULL,
  name TEXT NOT NULL,
  party TEXT,
  phone_albany TEXT,
  phone_district TEXT,
  email TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (chamber, district)
);

-- Enable RLS
ALTER TABLE legislators ENABLE ROW LEVEL SECURITY;

-- Allow public read access
CREATE POLICY "Public read access" ON legislators FOR SELECT USING (true);

-- Index for common queries
CREATE INDEX idx_legislators_chamber ON legislators (chamber);
CREATE INDEX idx_legislators_party ON legislators (party);

